// ERZEUGT von `npm run module:register` aus ui-debug-panel.element.scss — nicht von Hand ändern.
export const STIL = ":host{display:block}.debug-panel{background:var(--mat-sys-surface-container-low);color:var(--mat-sys-on-surface);border-top:1px solid var(--mat-sys-outline-variant);padding:10px 14px;font-size:.72rem;font-family:monospace;overflow-x:hidden;line-height:1.5;word-break:break-all;overflow-wrap:break-word}.debug-row{margin-bottom:2px;max-width:100%}.debug-label{font-weight:600;color:var(--mat-sys-primary)}.debug-trace-entry{margin:2px 0}.debug-parallel-header{font-weight:600;color:var(--mat-sys-on-surface-variant);margin:4px 0 2px;font-size:.82rem}.debug-parallel-stack{position:relative;background:var(--mat-sys-surface-container-high);border-radius:var(--mat-sys-corner-extra-small);padding:4px 0;margin-bottom:4px}.debug-parallel-task{background:color-mix(in srgb, var(--mat-sys-primary) 18%, var(--mat-sys-surface-container-high));border-left:2px solid var(--mat-sys-primary);border-radius:var(--mat-sys-corner-extra-small);padding:2px 6px;margin:2px 0;font-size:.78rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:flex;justify-content:space-between;gap:8px}.debug-parallel-task__label{overflow:hidden;text-overflow:ellipsis}.debug-parallel-task__time{flex-shrink:0;color:var(--mat-sys-on-surface-variant);font-variant-numeric:tabular-nums}.debug-section-title{font-weight:700;font-size:.72rem;color:var(--mat-sys-on-surface);margin:8px 0 4px;padding-top:6px;border-top:1px dashed var(--mat-sys-outline-variant);letter-spacing:.02em}.debug-section-title:first-of-type{margin-top:0;padding-top:0;border-top:none}.debug-warn{color:light-dark(#b45309, #e5a34a);font-weight:600}.debug-ok{color:light-dark(#047857, #5cc98f);font-weight:500;margin-left:4px}";
